#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<std::string> languages = {"HTML", "CSS", "JavaScript"};
    int index = 1;
    for (const auto& name : languages) {
        std::cout << index++ << ". " << name << '\n';
    }
    return 0;
}
